import{_ as t,o as r,c as d,a2 as a}from"./chunks/framework.CRfKVJQk.js";const u=JSON.parse('{"title":"Glossary","description":"Terms used across the React Native Liquid Glass docs: glass view, backdrop, material, renderer names, quality, and the support status labels.","frontmatter":{"description":"Terms used across the React Native Liquid Glass docs: glass view, backdrop, material, renderer names, quality, and the support status labels.","head":[["link",{"rel":"canonical","href":"https://sachinmeenasipl.github.io/react-native-glass-effect/reference/glossary"}],["meta",{"property":"og:url","content":"https://sachinmeenasipl.github.io/react-native-glass-effect/reference/glossary"}],["meta",{"property":"og:title","content":"Glossary · Liquid Glass for React Native"}],["meta",{"property":"og:description","content":"Terms used across the React Native Liquid Glass docs: glass view, backdrop, material, renderer names, quality, and the support status labels."}],["meta",{"name":"twitter:title","content":"Glossary · Liquid Glass for React Native"}],["meta",{"name":"twitter:description","content":"Terms used across the React Native Liquid Glass docs: glass view, backdrop, material, renderer names, quality, and the support status labels."}]]},"headers":[],"relativePath":"reference/glossary.md","filePath":"reference/glossary.md"}'),s={name:"reference/glossary.md"};function o(i,e,n,l,c,h){return r(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><p>The docs use these terms consistently. When a page says &quot;renderer&quot;, it means one of the renderers below.</p><h2 id="core-terms" tabindex="-1">Core terms <a class="header-anchor" href="#core-terms" aria-label="Permalink to &quot;Core terms&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Glass view</strong></td><td>Any component that draws glass: <code>LiquidGlassView</code> and everything built on it (<code>LiquidGlass</code>, <code>FrostedGlass</code>, <code>LiquidGlassButton</code>, <code>LiquidGlassCard</code>, <code>GlassAdjuster</code>&#39;s panel)</td></tr><tr><td><strong>Backdrop</strong></td><td>A <code>&lt;GlassBackdrop&gt;</code>: the content glass views blur and bend. Glass goes next to it, never inside it</td></tr><tr><td><strong>Material</strong></td><td>A named set of look values: <code>thin</code>, <code>regular</code>, <code>thick</code>, <code>clear</code>, <code>liquid</code>, <code>liquidClear</code>. See <a href="/react-native-glass-effect/features/materials">Materials</a></td></tr><tr><td><strong>Theme</strong></td><td>App-wide defaults set with <code>GlassThemeProvider</code></td></tr><tr><td><strong>Quality</strong></td><td>The rendering budget of a glass view: <code>auto</code>, <code>high</code>, <code>medium</code>, <code>low</code>, <code>static</code></td></tr><tr><td><strong>Native code</strong></td><td>The Android (Kotlin) and iOS (Objective-C++) parts of the library. Not available in Expo Go, tests or the web</td></tr><tr><td><strong>Web build</strong></td><td><code>lib/web</code>: the library without native code, chosen automatically by web bundlers</td></tr></tbody></table><h2 id="renderers" tabindex="-1">Renderers <a class="header-anchor" href="#renderers" aria-label="Permalink to &quot;Renderers&quot;">​</a></h2><p>A <strong>renderer</strong> is the code path that draws a glass view. <code>useGlassCapabilities().bestRenderer</code> reports which one a device uses.</p><table tabindex="0"><thead><tr><th>Renderer</th><th>Where</th><th>How it draws</th></tr></thead><tbody><tr><td><code>shader</code></td><td>Android 13+</td><td>GPU blur, then an AGSL refraction shader, then tint, rim light and border</td></tr><tr><td><code>blur</code></td><td>Android 12</td><td>GPU blur, then tint, rim light and border</td></tr><tr><td><code>compat</code></td><td>Android 7–11</td><td>A snapshot of the backdrop, blurred on the CPU</td></tr><tr><td><code>system-glass</code></td><td>iOS 26+</td><td>Apple&#39;s <code>UIGlassEffect</code></td></tr><tr><td><code>system-material</code></td><td>iOS 15–25</td><td>Apple&#39;s <code>UIVisualEffectView</code> blur materials</td></tr><tr><td><strong>iOS shader renderer</strong></td><td>iOS, with <code>iosRenderer=&quot;shader&quot;</code></td><td>The library&#39;s Metal renderer, matching Android. Reported as <code>system-glass</code> / <code>system-material</code> by <code>bestRenderer</code></td></tr><tr><td><strong>CSS renderer</strong></td><td>Web</td><td>CSS <code>backdrop-filter: blur() saturate()</code> with tint, border and corners. Reported as <code>fallback</code> by <code>bestRenderer</code></td></tr><tr><td><strong>Plain fallback</strong></td><td>Expo Go, tests, missing native code</td><td>A tinted view with no blur. Also reported as <code>fallback</code></td></tr></tbody></table><h2 id="support-status-labels" tabindex="-1">Support status labels <a class="header-anchor" href="#support-status-labels" aria-label="Permalink to &quot;Support status labels&quot;">​</a></h2><p>Tables across the docs use these labels:</p><table tabindex="0"><thead><tr><th>Label</th><th>Meaning</th></tr></thead><tbody><tr><td>✅</td><td>Supported: the prop or feature works as described</td></tr><tr><td>◐</td><td>Approximated: a similar effect drawn a different way (for example the rim light on Android 12)</td></tr><tr><td>⚙️</td><td>System-controlled: the platform draws it; the prop has little or no effect</td></tr><tr><td>—</td><td>Ignored: the prop is accepted and has no effect. It never throws</td></tr><tr><td>⛔</td><td>Not supported</td></tr><tr><td>❔</td><td>Not yet tested on this platform</td></tr></tbody></table><p>For versions and what has actually been tested, see <a href="/react-native-glass-effect/reference/compatibility">Compatibility</a>.</p>',11)])])}const b=t(s,[["render",o]]);export{u as __pageData,b as default};
